comments.body:
I think it would be good to add a new test case here to check that a replecemnt is requested even when the candidate with `m_relays_txs=false` cannot be evicted yet because it is younger than MINIMUM_CONNECT_TIME

```cpp
    vNodes[1]->fDisconnect = false;
    AddRandomOutboundPeer(id, vNodes, *peerLogic, *connman, ConnectionType::OUTBOUND_FULL_RELAY);
    vNodes.back()->m_relays_txs = false;
    AddRandomOutboundPeer(id, vNodes, *peerLogic, *connman, ConnectionType::OUTBOUND_FULL_RELAY);
    vNodes.back()->m_relays_txs = true;
    clock += 1s;
    peerLogic->CheckForStaleTipAndEvictPeers();
    BOOST_CHECK(connman->GetReplaceNoTxRelayPeer());
    for (const CNode* node : vNodes) {
        BOOST_CHECK(!node->fDisconnect);
    }
```

